styles:
.bc-row { padding: 1rem 0; border-bottom: 1px dashed var(--is-border); }
    .bc-row:last-child { border-bottom: 0; }

    .bc-check { display: grid; gap: 14px; }
    .bc-case {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      flex-wrap: wrap;
      padding: 0.9rem 0;
      border-bottom: 1px dashed var(--is-border);
    }
    .bc-case:last-child { border-bottom: 0; }
    /* Escala tipografica de esta seccion: DOS pasos declarados sobre el cuerpo
       (1rem = 15px de presentation.css) → 0.75rem para etiquetas, 1.25rem para
       el titulo. Ratio ~1.33 entre pasos.
       El texto normal NO declara font-size: un 0.95rem sobre un cuerpo de 1rem
       no es jerarquia, es un duplicado que aplana la escala. */
    .bc-case dl {
      margin: 0;
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 2px 0.75rem;
      align-content: center;
    }
    .bc-case dt { color: var(--is-text-soft); font-size: 0.75rem; align-self: center; }
    .bc-case dd { margin: 0; }
    .bc-out { font-family: var(--is-mono, ui-monospace, monospace); letter-spacing: 0.04em; color: var(--is-accent); }

    .bc-verify {
      margin-top: 1.1rem;
      padding: 1rem 1.1rem;
      border: 1px solid var(--is-border);
      border-radius: 0.6rem;
      background: var(--is-bg-elev);
    }
    .bc-verify h3 { margin: 0 0 0.35rem; font-size: 1.25rem; }
    .bc-verify ol { margin: 0.5rem 0 0.9rem; padding-left: 1.15rem; display: grid; gap: 3px; }
    .bc-verify__actions { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; }
    .bc-msg { font-size: 0.75rem; color: var(--is-accent); }

